import { readFileSync, writeFileSync } from "node:fs";
const handler = readFileSync("supabase/functions/faznota-connection/handler.ts", "utf8");
const entry = readFileSync("supabase/functions/faznota-connection/index.ts", "utf8").replace(
  'import { createHandler } from "./handler.ts";\n',
  "",
);
writeFileSync(
  "deploy/faznota-connection.ts",
  "// Generated by node scripts/build-faznota-dashboard.mjs. No credentials belong in this file.\n" +
    handler +
    "\n" +
    entry,
);
